import{_ as a,o as t,c as l,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Orchestrator Meeting 2021-06-29","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2021-06-29","date":"2021-06-29T00:00:00.000Z","updated":"2021-08-25T00:00:00.000Z","tags":["Ceph","分布式存储","OpenShift","Rook","Self Orchestrator"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-06-29.md","filePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-06-29.md","lastUpdated":1780460162000}'),r={name:"posts/2021/Ceph_Orchestrator_Meeting_2021-06-29.md"};function o(s,e,n,h,d,c){return t(),l("div",null,[...e[0]||(e[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-osd自我编排器中的实现" tabindex="-1">会议主题：OSD自我编排器中的实现 <a class="header-anchor" href="#会议主题-osd自我编排器中的实现" aria-label="Permalink to &quot;会议主题：OSD自我编排器中的实现&quot;">​</a></h4><h4 id="参会人员" tabindex="-1">参会人员： <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员：&quot;">​</a></h4><ul><li>会议主持人：[主持人姓名]</li><li>主要发言人：Chris（OCS操作界面负责人）</li><li>其他参会人员：[其他参会人员姓名]</li></ul><h4 id="讨论议题" tabindex="-1">讨论议题： <a class="header-anchor" href="#讨论议题" aria-label="Permalink to &quot;讨论议题：&quot;">​</a></h4><ol><li><p><strong>PV（持久卷）的获取与管理</strong></p><ul><li>如何将PV引入自我编排器（Self Orchestrator）。</li><li>如何使用自我编排器在PV上创建OSD。</li></ul></li><li><p><strong>现有问题与挑战</strong></p><ul><li>处理本地持久卷（Local Persistent Volumes）与PV及声明（Claims）的关系。</li><li>在OCS（OpenShift Container Storage）中实现上述流程的挑战。</li></ul></li><li><p><strong>技术细节与演示</strong></p><ul><li>Chris演示了如何在OpenShift UI中通过OCS操作符创建PV和OSD。</li><li>讨论了LSO（Local Storage Operator）的使用，包括节点磁盘的发现和存储类的创建。</li></ul></li><li><p><strong>后续行动计划</strong></p><ul><li>探索LSO作为库的嵌入方式，而非独立操作符。</li><li>讨论Rook支持多种存储类的PV，而不仅是LSO。</li><li>考虑通过CSI（Container Storage Interface）标准管理本地硬件。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>明确Rook与LSO的集成方式，以及如何处理不同存储类的PV。</li><li>计划编写更具体的技术提案，以便深入讨论和实施。</li></ul><h4 id="后续行动" tabindex="-1">后续行动： <a class="header-anchor" href="#后续行动" aria-label="Permalink to &quot;后续行动：&quot;">​</a></h4><ul><li>继续实验和研究LSO的嵌入方式。</li><li>编写具体的技术提案，以待下次会议讨论。</li><li>考虑CSI标准在本地存储管理中的应用。</li></ul><h4 id="备注" tabindex="-1">备注： <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注：&quot;">​</a></h4><ul><li>会议中提到了OpenEBS作为另一个本地存储管理选项，但目前主要关注LSO。</li><li>讨论了在Rook中实现对本地硬件的发现和管理，以及如何与现有的存储操作符（如LSO）协同工作。</li></ul><h4 id="会议总结" tabindex="-1">会议总结： <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;会议总结：&quot;">​</a></h4><p>本次会议重点讨论了在Ceph Orchestrator中使用自我编排器创建OSD的过程，并探讨了与OpenShift和Rook集成的技术细节。会议还确定了后续行动计划，包括深入研究LSO的集成方式，编写技术提案，并考虑CSI标准在本地存储管理中的应用。</p>',14)])])}const S=a(r,[["render",o]]);export{u as __pageData,S as default};
